// Registro de educação alimentar: shared records plus durable photo attachments.
let foodDraft=null,foodBusy=false;
const foodColumns=[['objectives','Objetivos'],['themes','Temas / conteúdos'],['activities','Atividades / estratégias / dinâmicas'],['resources','Recursos necessários'],['responsible','Responsável']];
const foodFields=[['school','Nome da unidade escolar'],['className','Turma'],['audience','Público'],['participants','Número de participantes'],['place','Local'],['date','Data'],['duration','Duração'],['partners','Parceiros']];
const foodEmptyRow=()=>Object.fromEntries(foodColumns.map(([key])=>[key,'']));
function foodToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function foodPhotoUrl(photo){return photo.preview||(/^[a-f0-9-]{36}$/.test(photo.id||'')?location.origin+'/api/app/documents/'+photo.id+'/file?view=1':'')}
function foodNewData(){return {school:'CEI Lindolpho José da Silva',className:'',audience:'',participants:'',place:'CEI Lindolpho José da Silva',date:foodToday(),duration:'',partners:'',rows:[foodEmptyRow()],evaluation:'',photos:[],includePhotos:true}}
window.openFoodPractice=id=>{const record=(state.generatedDocs||[]).find(x=>x.id===id);foodDraft={id:record?.id||uid(),saved:!!record,data:record?structuredClone(record.data):foodNewData()};foodDraft.data.rows ||= [foodEmptyRow()];foodDraft.data.photos ||= [];document.getElementById('foodPracticeModal').classList.remove('hidden');renderFoodPractice()};
function foodCapture(){if(!foodDraft)return;for(const [key] of foodFields)foodDraft.data[key]=document.getElementById('food-'+key)?.value||'';foodDraft.data.evaluation=document.getElementById('food-evaluation')?.value||'';foodDraft.data.includePhotos=!!document.getElementById('food-includePhotos')?.checked;document.querySelectorAll('[data-food-row]').forEach(el=>{foodDraft.data.rows[Number(el.dataset.foodRow)][el.dataset.foodColumn]=el.value});document.querySelectorAll('[data-food-caption]').forEach(el=>foodDraft.data.photos[Number(el.dataset.foodCaption)].caption=el.value)}
function renderFoodPractice(){const d=foodDraft.data;document.getElementById('foodPracticeBody').innerHTML=`<div class="food-intro"><img src="/araquari-logo-atual.png" alt="Governo de Araquari"><div><h2 id="foodPracticeTitle">${foodDraft.saved?'Editar registro':'Registro de prática alimentar'}</h2><p>Educação Alimentar e Nutricional · Secretaria Municipal de Educação</p></div></div><p class="hint">Preencha os campos, acrescente as atividades e selecione as fotografias. O documento e suas fotos ficam no arquivo compartilhado do site.</p><form id="foodPracticeForm"><fieldset><legend>1. Identificação da prática</legend><div class="form-grid">${foodFields.map(([key,label])=>`<label>${label}${['school','className','date'].includes(key)?' *':''}<input id="food-${key}" type="${key==='date'?'date':key==='participants'?'number':'text'}" ${['school','className','date'].includes(key)?'required':''} ${key==='participants'?'min="0" step="1"':''} maxlength="250" value="${esc(d[key]||'')}"></label>`).join('')}</div></fieldset><fieldset><legend>2. Desenvolvimento da prática</legend><div class="food-rows">${d.rows.map((row,i)=>`<section class="food-row"><div class="food-row-head"><b>Atividade ${i+1}</b><button type="button" onclick="foodRemoveRow(${i})" ${d.rows.length===1?'disabled':''}>Remover atividade</button></div><div class="food-row-fields">${foodColumns.map(([key,label])=>`<label>${label}<textarea data-food-row="${i}" data-food-column="${key}" rows="3" maxlength="1800">${esc(row[key]||'')}</textarea></label>`).join('')}</div></section>`).join('')}</div><button type="button" onclick="foodAddRow()">+ Adicionar atividade</button></fieldset><fieldset><legend>3. Avaliação</legend><label for="food-evaluation">Resultados, participação e observações</label><textarea id="food-evaluation" rows="5" maxlength="6000">${esc(d.evaluation||'')}</textarea></fieldset><fieldset><legend>4. Fotografias (opcional)</legend><p class="hint">JPG, PNG ou WebP, até 20 MB por foto. O sistema ajusta a resolução e o tamanho, preserva a proporção e organiza quatro fotos por página A4, sem recortar. Você pode alterar a ordem e adicionar legendas.</p><input type="file" id="food-files" multiple accept="image/jpeg,image/png,image/webp" aria-label="Selecionar fotografias" onchange="foodAddPhotos(this)"><label class="food-checkbox"><input type="checkbox" id="food-includePhotos" ${d.includePhotos!==false?'checked':''}> Incluir páginas de fotografias na impressão</label><p class="hint">${d.photos.length} foto(s) · ${Math.ceil(d.photos.length/4)} página(s) extra(s). A última página pode ter menos de quatro fotos.</p><div class="food-photo-list">${d.photos.map((photo,i)=>`<figure><img src="${esc(foodPhotoUrl(photo))}" alt="Fotografia ${i+1}"><figcaption><label>Legenda da foto ${i+1}<input data-food-caption="${i}" maxlength="160" value="${esc(photo.caption||'')}" placeholder="Legenda opcional"></label><div class="food-photo-actions"><button type="button" onclick="foodMovePhoto(${i},-1)" ${i===0?'disabled':''} aria-label="Mover foto ${i+1} para antes">←</button><button type="button" onclick="foodMovePhoto(${i},1)" ${i===d.photos.length-1?'disabled':''} aria-label="Mover foto ${i+1} para depois">→</button><button type="button" onclick="foodRemovePhoto(${i})">Remover</button></div></figcaption></figure>`).join('')}</div></fieldset></form>`}
window.foodAddRow=()=>{foodCapture();foodDraft.data.rows.push(foodEmptyRow());renderFoodPractice()};
window.foodRemoveRow=i=>{foodCapture();if(foodDraft.data.rows.length>1)foodDraft.data.rows.splice(i,1);renderFoodPractice()};
window.foodMovePhoto=(i,step)=>{foodCapture();const photos=foodDraft.data.photos,next=i+step;if(next>=0&&next<photos.length)[photos[i],photos[next]]=[photos[next],photos[i]];renderFoodPractice()};
window.foodRemovePhoto=i=>{foodCapture();const [photo]=foodDraft.data.photos.splice(i,1);if(photo?.preview)URL.revokeObjectURL(photo.preview);renderFoodPractice()};
function foodSetBusy(busy,message=''){foodBusy=busy;document.querySelectorAll('#foodPracticeModal button,#foodPracticeModal input,#foodPracticeModal textarea').forEach(el=>el.disabled=busy);document.getElementById('foodPracticeStatus').textContent=message}
async function foodOptimize(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use fotografias JPG, PNG ou WebP.');if(file.size>20*1024*1024)throw Error('Cada fotografia deve ter até 20 MB.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.84));if(!blob)throw Error('Não foi possível processar a imagem.');return new File([blob],'foto.jpg',{type:'image/jpeg'})}
window.foodAddPhotos=async input=>{foodCapture();const files=[...input.files];foodSetBusy(true,'Preparando fotografias…');try{for(let i=0;i<files.length;i++){document.getElementById('foodPracticeStatus').textContent=`Preparando foto ${i+1} de ${files.length}…`;const file=await foodOptimize(files[i]);foodDraft.data.photos.push({file,preview:URL.createObjectURL(file),caption:''})}}catch(error){alert(error.message)}finally{foodSetBusy(false);renderFoodPractice()}};
window.closeFoodPractice=()=>{if(foodBusy)return;if(!confirm('Fechar este formulário? As alterações que ainda não foram salvas serão descartadas.'))return;foodDraft?.data.photos.forEach(p=>{if(p.preview)URL.revokeObjectURL(p.preview)});foodDraft=null;document.getElementById('foodPracticeModal').classList.add('hidden')};
window.saveFoodPractice=async print=>{if(foodBusy)return;foodCapture();if(!document.getElementById('foodPracticeForm').reportValidity())return;const popup=print?window.open('','_blank'):null;if(print&&!popup)return alert('Permita abrir a janela de impressão para este site.');if(popup){popup.document.write('<p>Salvando registro e preparando impressão…</p>');popup.document.close()}foodSetBusy(true,'Salvando fotografias e registro…');try{await sharedQueue;if(!sharedActive)throw Error('Conecte à base compartilhada em Segurança antes de salvar.');for(let i=0;i<foodDraft.data.photos.length;i++){const photo=foodDraft.data.photos[i];if(!photo.file)continue;document.getElementById('foodPracticeStatus').textContent=`Salvando fotografia ${i+1} de ${foodDraft.data.photos.length}…`;const form=new FormData();form.set('file',photo.file);form.set('documentId',foodDraft.id);const response=await fetch('/api/app/document-photos',{method:'POST',body:form});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível salvar a fotografia.');photo.id=result.id;delete photo.file;URL.revokeObjectURL(photo.preview);delete photo.preview}
 const data={...foodDraft.data,photos:foodDraft.data.photos.map(p=>({id:p.id,caption:p.caption||''}))};const existing=state.generatedDocs.find(g=>g.id===foodDraft.id),now=new Date().toISOString(),record={ownerEmail:existing?.ownerEmail||window.CEI_SESSION?.email,id:foodDraft.id,template:'praticaAlimentar',name:'Registro de prática alimentar',date:formatDate(data.date),reference:[data.className,data.rows[0]?.themes].filter(Boolean).join(' — '),data,createdAt:existing?.createdAt||now,updatedAt:now};const index=state.generatedDocs.findIndex(g=>g.id===record.id);if(index<0)state.generatedDocs.push(record);else state.generatedDocs[index]=record;await writeDataFile(false);await sharedQueue;if(!sharedActive||localStorage.getItem('cei-shared-dirty')==='1')throw Error('O registro está preservado como rascunho, mas o servidor não confirmou a gravação. Tente novamente.');foodDraft.saved=true;document.getElementById('foodPracticeStatus').textContent='Registro salvo no servidor e disponível para todos.';if(document.getElementById('categoryGenerated'))filterCategoryGenerated();if(print)foodOpenPrint(data,popup);notify('Registro de prática alimentar salvo.');
 }catch(error){if(popup)popup.close();document.getElementById('foodPracticeStatus').textContent=error.message;alert(error.message)}finally{const message=document.getElementById('foodPracticeStatus').textContent;foodSetBusy(false,message);renderFoodPractice()}};
function foodPhotoGroups(photos){const pages=[];for(let i=0;i<photos.length;i+=4)pages.push(photos.slice(i,i+4));return pages}
function foodPrintHTML(data){const header=`<header class="food-letterhead"><img src="${location.origin}/araquari-logo-atual.png" alt="Governo de Araquari"><div>Prefeitura Municipal de Araquari<br><strong>Secretaria Municipal de Educação</strong></div></header>`;const value=v=>esc(v||'—').replace(/\n/g,'<br>');const groups=data.includePhotos===false?[]:foodPhotoGroups(data.photos||[]);return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Registro de prática alimentar — ${esc(data.className||'CEI')}</title><link rel="stylesheet" href="${location.origin}/food-practice-print.css"></head><body><nav class="print-controls"><button id="foodPrintButton" disabled onclick="window.print()">Imprimir / Salvar PDF</button><span id="foodPrintStatus">Preparando imagens…</span></nav><main><section class="food-form-page">${header}<div class="food-print-title"><span>REGISTRO PEDAGÓGICO</span><h1>Prática de Educação Alimentar e Nutricional</h1></div><div class="food-identification">${foodFields.map(([key,label])=>`<div class="${key==='school'?'span-2':key==='partners'?'span-4':''}"><b>${label}</b><p>${value(key==='date'?formatDate(data.date):data[key])}</p></div>`).join('')}</div><h2>Desenvolvimento da prática</h2><table><colgroup><col style="width:20%"><col style="width:18%"><col style="width:26%"><col style="width:19%"><col style="width:17%"></colgroup><thead><tr>${foodColumns.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${(data.rows||[]).map(row=>`<tr>${foodColumns.map(([key])=>`<td>${value(row[key])}</td>`).join('')}</tr>`).join('')}</tbody></table><section class="food-evaluation"><h2>Avaliação</h2><p>${value(data.evaluation)}</p></section><footer>CEI Lindolpho José da Silva · Educação Alimentar e Nutricional</footer></section>${groups.map((photos,page)=>`<section class="food-photo-page">${header}<div class="food-photo-title"><h2>Registro fotográfico</h2><p>${value(data.school)} · ${value(data.className)} · ${value(formatDate(data.date))}</p></div><div class="food-print-grid">${photos.map((photo,i)=>`<figure><div class="food-image-frame"><img src="${esc(foodPhotoUrl(photo))}" alt="Fotografia ${page*4+i+1}"></div><figcaption><strong>${String(page*4+i+1).padStart(2,'0')}</strong> ${esc(photo.caption||'Registro da prática alimentar')}</figcaption></figure>`).join('')}</div><footer>Anexo fotográfico ${page+1} de ${groups.length} · ${data.photos.length} fotografia(s)</footer></section>`).join('')}</main><script>window.addEventListener('load',()=>{Promise.all(Array.from(document.images).map(img=>img.complete?(img.naturalWidth?Promise.resolve():Promise.reject()):new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject}))).then(()=>{document.getElementById('foodPrintButton').disabled=false;document.getElementById('foodPrintStatus').textContent='Pronto. Formato A4 paisagem. Desative cabeçalhos e rodapés do navegador.'}).catch(()=>{document.getElementById('foodPrintStatus').textContent='Uma imagem não carregou. Reabra a visualização antes de imprimir.'});});<\/script></body></html>`}
function foodOpenPrint(data,popup){const win=popup||window.open('','_blank');if(!win)return alert('Permita abrir a janela de impressão para este site.');win.document.open();win.document.write(foodPrintHTML(data));win.document.close()}
// Integrate with all existing document archive actions without creating copies.
documentTemplates.praticaAlimentar={icon:'🥕',name:'Registro de prática alimentar',description:'Educação Alimentar e Nutricional, com fotografias organizadas em quatro por página.',fields:[]};
const foodPreviousOpen=window.openDocGen,foodPreviousPreview=window.previewGenerated,foodPreviousEdit=window.reopenGenerated;
window.openDocGen=id=>id==='praticaAlimentar'?openFoodPractice():foodPreviousOpen(id);
window.previewGenerated=id=>{const g=state.generatedDocs.find(x=>x.id===id);if(g?.template==='praticaAlimentar')return foodOpenPrint(g.data);return foodPreviousPreview(id)};
window.reopenGenerated=id=>{const g=state.generatedDocs.find(x=>x.id===id);if(g?.template==='praticaAlimentar')return openFoodPractice(id);return foodPreviousEdit(id)};
document.body.insertAdjacentHTML('beforeend',`<div id="foodPracticeModal" class="modal hidden" role="dialog" aria-modal="true" aria-labelledby="foodPracticeTitle"><div class="modal-card food-modal-card"><div id="foodPracticeBody"></div><p id="foodPracticeStatus" role="status" aria-live="polite"></p><div class="actions food-footer"><button onclick="closeFoodPractice()">Fechar</button><button onclick="saveFoodPractice(false)">Salvar registro</button><button class="primary" onclick="saveFoodPractice(true)">Salvar e visualizar impressão</button></div></div></div>`);
